-async function sendPush(
-  supabase: SupabaseClient,
-  userId: string,
-  message: string
-) {
-  const publicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY;
-  const privateKey = process.env.VAPID_PRIVATE_KEY;
-  const subject =
-    process.env.VAPID_SUBJECT || "mailto:misaki@example.com";
-
