-
-      await supabase
-        .from("push_subscriptions")
-        .update({ last_used_at: new Date().toISOString() })
-        .eq("id", subscription.id);
-    } catch (error: any) {
-      const statusCode = Number(error?.statusCode);
-      if (statusCode === 404 || statusCode === 410) {
-        await supabase
-          .from("push_subscriptions")
-          .delete()
-          .eq("id", subscription.id);
-        removed += 1;
-      } else {
-        console.error("BODY CLOCK PUSH ERROR:", error);
-      }
-    }
-  }
-
-  return { sent, removed };
-}
