        usageCountToday
    );

  const freeLimitReached =
    accountLoaded &&
    !isPremium &&
    usageCountToday >=
      FREE_DAILY_LIMIT;

  useEffect(
    () => {
      let active =
        true;

      async function loadEntitlement(
        userId:
          string
      ) {
        for (
          let attempt =
            0;
          attempt <
            5;
          attempt +=
            1
        ) {
          const {
            data,
            error,
          } =
            await supabase
              .from(
                "user_entitlements"
              )
              .select(
                "plan,premium_until"
              )
              .eq(
                "user_id",
                userId
              )
              .maybeSingle();

          if (
            error
          ) {
            throw error;
          }

          if (
            data
          ) {
            return isPremiumActive(
              data.plan,
              data.premium_until
            );
          }

          await new Promise(
            (
              resolve
            ) =>
              window.setTimeout(
                resolve,
                350
              )
          );
        }

        return false;
      }

      async function loadDailyUsage() {
        const {
          data,
          error,
        } =
          await supabase.rpc(
            "get_daily_message_usage"
          );

        if (
          error
        ) {
          throw error;
        }

        const usage =
          getFirstRpcRow<
            UsageRpcResult
          >(
            data
          );

        return {
          count:
            typeof usage
              ?.message_count ===
              "number"
              ? Math.max(
                  0,
                  Math.floor(
                    usage
                      .message_count
                  )
                )
              : 0,

          isPremium:
            usage
              ?.is_premium ===
            true,
        };
      }

      async function initializeAccount() {
        try {
          const {
            data:
              sessionData,
            error:
              sessionError,
          } =
            await supabase
              .auth
              .getSession();

          if (
            sessionError
          ) {
            throw sessionError;
          }

          let user =
            sessionData
              .session
              ?.user ??
            null;

          if (
            !user
          ) {
            const {
              data:
                signInData,
              error:
                signInError,
            } =
              await supabase
                .auth
                .signInAnonymously();

            if (
              signInError
            ) {
              throw signInError;
            }

            user =
              signInData
                .user ??
              null;
          }

          if (
            !user
          ) {
            throw new Error(
              "Supabase user was not created."
            );
          }

          const [
            entitlementPremium,
            usage,
          ] =
            await Promise
              .all([
                loadEntitlement(
                  user.id
                ),

                loadDailyUsage(),
              ]);

          if (
            !active
          ) {
            return;
          }

          const premium =
            entitlementPremium ||
            usage
              .isPremium;

          setPlan(
            premium
              ? "premium"
              : "free"
          );

          setDailyUsage({
            date:
              getJapanDateKey(),

            count:
              usage.count,
          });
        } catch (
          error
        ) {
          console.error(
            "Supabase account initialization failed:",
            error
          );

          if (
            active
          ) {
            setPlan(
              "free"
            );

            setDailyUsage({
              date:
                getJapanDateKey(),

              count:
                0,
            });
          }
        } finally {
          if (
            active
          ) {
            setAccountLoaded(
              true
            );
          }
        }
      }

      initializeAccount();

      return () => {
        active =
          false;
      };
    },
    []
  );

  useEffect(
    () => {
      if (
        !accountLoaded
      ) {
        return;
      }

      if (
        isPremium
      ) {
        setShowPremium(
          false
        );

        return;
      }

      if (
        usageCountToday >=
        FREE_DAILY_LIMIT
      ) {
        setShowPremium(
          true
        );
      }
    },
    [
      accountLoaded,
      isPremium,
      usageCountToday,
    ]
  );

  useEffect(
    () => {
      if (
        "serviceWorker" in
        navigator
      ) {
        navigator
          .serviceWorker
          .register(
            "/sw.js"
          )
          .then(
            (
              registration
            ) => {
              console.log(
                "Service Worker registered:",
                registration
              );
            }
          )
          .catch(
            (
              error
            ) => {
              console.error(
                "Service Worker registration failed:",
                error
              );
            }
          );
      }
    },
    []
  );

  useEffect(
    () => {
      if (
        !(
          "Notification" in
          window
        )
      ) {
        setNotificationPermission(
          "unsupported"
        );

        return;
      }

      setNotificationPermission(
        Notification
          .permission
      );
    },
    []
  );

  useEffect(
    () => {
      try {
        const savedMessages =
          localStorage
            .getItem(
              STORAGE_KEY
            );

        const savedMemory =
          localStorage
            .getItem(
              MEMORY_KEY
            );

        const savedRelationship =
          localStorage
            .getItem(
              RELATIONSHIP_KEY
            );

        const savedTodayMemory =
          localStorage
            .getItem(
              MISAKI_TODAY_MEMORY_KEY
            );

        let parsedMessages:
          | ChatMessage[]
          | null =
          null;

        if (
          savedMessages
        ) {
          const parsed =
            JSON.parse(
              savedMessages
            );

          if (
            Array.isArray(
              parsed
            )
          ) {
            parsedMessages =
              parsed
                .filter(
                  (
                    item
                  ) =>
                    item &&
                    (
                      item
                        .role ===
                        "user" ||
                      item
                        .role ===
                        "misaki"
                    ) &&
                    typeof item
                      .text ===
                      "string"
                )
                .slice(
                  -MAX_MESSAGES
                );

            setMessages(
              parsedMessages
            );
          }
        }

        if (
          savedMemory
        ) {
          const parsedMemory =
            JSON.parse(
              savedMemory
            );

          if (
            Array.isArray(
              parsedMemory
            )
          ) {
            setMemory(
              parsedMemory
                .filter(
                  (
                    item
                  ) =>
                    typeof item ===
                    "string"
                )
            );
          }
        }

        if (
          savedRelationship
        ) {
          const parsedPoints =
            Number(
              savedRelationship
            );

          if (
            Number
              .isFinite(
                parsedPoints
              ) &&
            parsedPoints >=
              0
          ) {
            setRelationshipPoints(
              Math.floor(
                parsedPoints
              )
            );
          }
        } else if (
          parsedMessages
        ) {
          const previousUserMessages =
            parsedMessages
              .filter(
                (
                  item
                ) =>
                  item.role ===
                  "user"
              )
              .length;

          setRelationshipPoints(
            previousUserMessages
          );
        }

        const currentDate =
          getJapanDateKey();

        if (
          savedTodayMemory
        ) {
          const parsedTodayMemory =
            JSON.parse(
              savedTodayMemory
            );

          if (
            parsedTodayMemory &&
            parsedTodayMemory
              .date ===
              currentDate &&
            Array.isArray(
              parsedTodayMemory
                .items
            )
          ) {
            setMisakiTodayMemory({
              date:
                currentDate,

              items:
                parsedTodayMemory
                  .items
                  .filter(
                    (
                      item:
                        unknown
                    ) =>
                      typeof item ===
                        "string" &&
                      item
                        .trim()
                        .length >
                        0
                  )
                  .map(
                    (
                      item:
                        string
                    ) =>
                      item
                        .trim()
                  )
                  .slice(
                    -12
                  ),
            });
          } else {
            setMisakiTodayMemory({
              date:
                currentDate,

              items:
                [],
            });
          }
        } else {
          setMisakiTodayMemory({
            date:
              currentDate,

            items:
              [],
          });
        }
      } catch (
        error
      ) {
        console.error(
          "Failed to load saved data:",
          error
        );

        const currentDate =
          getJapanDateKey();

        setMisakiTodayMemory({
          date:
            currentDate,

          items:
            [],
        });
      } finally {
        setLoaded(
          true
        );
      }
    },
    []
  );

  useEffect(
    () => {
      if (
        !loaded
      ) {
        return;
      }

      try {
        const limitedMessages =
          messages
            .slice(
              -MAX_MESSAGES
            );

        localStorage
          .setItem(
            STORAGE_KEY,

            JSON.stringify(
              limitedMessages
            )
          );
      } catch (
        error
      ) {
        console.error(
          "Failed to save chat history:",
          error
        );
      }
    },
    [
      messages,
      loaded,
    ]
  );

  useEffect(
    () => {
      if (
        !loaded
      ) {
        return;
      }

      try {
        localStorage
          .setItem(
            MEMORY_KEY,

            JSON.stringify(
              memory
            )
          );
      } catch (
        error
      ) {
        console.error(
          "Failed to save memory:",
          error
        );
      }
    },
    [
      memory,
      loaded,
    ]
  );

  useEffect(
    () => {
      if (
        !loaded
      ) {
        return;
      }

      try {
        const currentDate =
          getJapanDateKey();

        const safeTodayMemory =
          misakiTodayMemory
            .date ===
            currentDate
            ? misakiTodayMemory
            : {
                date:
                  currentDate,

                items:
                  [],
              };

        localStorage
          .setItem(
            MISAKI_TODAY_MEMORY_KEY,

            JSON.stringify(
              safeTodayMemory
            )
          );

        if (
          misakiTodayMemory
            .date !==
          currentDate
        ) {
          setMisakiTodayMemory(
            safeTodayMemory
          );
        }
      } catch (
        error
      ) {
        console.error(
          "Failed to save Misaki today memory:",
          error
        );
      }
    },
    [
      misakiTodayMemory,
      loaded,
    ]
  );

  useEffect(
    () => {
      if (
        !loaded
      ) {
        return;
      }

      try {
        localStorage
          .setItem(
            RELATIONSHIP_KEY,

            String(
              relationshipPoints
            )
          );
      } catch (
        error
      ) {
        console.error(
          "Failed to save relationship points:",
          error
        );
      }
    },
    [
      relationshipPoints,
      loaded,
    ]
  );

  async function getAccessToken() {
    const {
      data,
      error,
    } =
      await supabase
        .auth
        .getSession();

    if (
