-function getHour(currentTime: string) {
-  const match = currentTime.match(/(\d{1,2}):(\d{2})/);
-
-  if (!match) {
-    return 18;
-  }
-
-  const hour = Number(match[1]);
-
-  if (!Number.isFinite(hour)) {
-    return 18;
-  }
-
-  return Math.max(0, Math.min(23, hour));
-}
