-  const totalWeight = photos.reduce(
-    (sum, photo) => sum + Math.max(1, photo.weight),
-    0
-  );
-
-  let target = seed % totalWeight;
-
-  for (const photo of photos) {
-    const weight = Math.max(1, photo.weight);
-
-    if (target < weight) {
-      return photo;
-    }
-
-    target -= weight;
-  }
-
-  return photos[0] ?? null;
-}
